import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import './App.css';

function App() {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [role, setRole] = useState('Frontend Developer');
  const [feedback, setFeedback] = useState('');
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSubmitChat = async (event) => {
    event.preventDefault();
    if (!inputMessage.trim()) return;

    addMessage(inputMessage, 'user');

    try {
      const response = await fetch('http://localhost:3000/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: inputMessage, role }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Unable to communicate with the server.', 'bot');
    }

    setInputMessage('');
  };

  const handleWrapUp = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: '__WRAP_UP__', role }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Could not finish the interview.', 'bot');
    }
  };

  const handleFeedbackSubmit = async (e) => {
    e.preventDefault();
    await fetch('http://localhost:3000/api/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ feedback }),
    });
    alert("Thank you for your feedback!");
    setFeedback('');
  };

  const handleFeedback = () => {
    window.location.href = '/feedback'; // ไปหน้า feedback ใหม่
  };

  const addMessage = (text, sender) => {
    setMessages((prev) => [...prev, { text, sender }]);
  };

  return (
    <Router>
      <Routes>
        {/* หน้าแรกของแอป: Chat Component */}
        <Route
          path="/"
          element={
            <div className="App">
              <div className="chat-window">
                <h2>Mock Interview Chatbot</h2>
                <select value={role} onChange={(e) => setRole(e.target.value)}>
                  <option value="Frontend Developer">Frontend Developer</option>
                  <option value="Backend Developer">Backend Developer</option>
                  <option value="Data Scientist">Data Scientist</option>
                  <option value="UX Designer">UX Designer</option>
                </select>

                <ul className="messages-list">
                  {messages.map((msg, i) => (
                    <li key={i} className={`message ${msg.sender}`}>
                      {msg.text}
                    </li>
                  ))}
                  <div ref={messagesEndRef} />
                </ul>

                <form onSubmit={handleSubmitChat} className="input-area">
                  <input
                    type="text"
                    value={inputMessage}
                    onChange={(e) => setInputMessage(e.target.value)}
                    placeholder="Your response..."
                  />
                  <button type="submit">Send</button>
                  <button onClick={handleWrapUp} className="wrap-up-button">Finish Interview</button>
                </form>
                <button onClick={handleFeedback} className="wrap-up-button">Feedback</button>
              </div>
            </div>
          }
        />

        {/* หน้า Feedback */}
        <Route
          path="/feedback"
          element={
            <div className="App">
              <h2>Feedback</h2>
              <form onSubmit={handleFeedbackSubmit}>
                <textarea
                  value={feedback}
                  onChange={(e) => setFeedback(e.target.value)}
                  placeholder="Leave your feedback here..."
                  rows={5}
                />
                <br />
                <button type="submit">Submit Feedback</button>
              </form>
            </div>
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
